import json
import heapq

def main():
    with open('/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a48q6jxk/graph.json', 'r') as f:
        data = json.load(f)

    nodes = data['nodes']
    edges = data['edges']

    adj = {node: [] for node in nodes}
    for e in edges:
        adj[e['from']].append((e['to'], e['weight']))
        adj[e['to']].append((e['from'], e['weight']))

    INF = float('inf')
    dist = {node: INF for node in nodes}
    dist['A'] = 0

    pq = [(0, 'A')]
    visited = set()

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)
        for v, w in adj[u]:
            if v not in visited:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist[node]
        if d == INF:
            print(f"A -> {node}: inf")
        elif d == int(d):
            print(f"A -> {node}: {int(d)}")
        else:
            print(f"A -> {node}: {d}")

main()

