import json


def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        for key in a:
            if key in b:
                result[key] = deep_merge(a[key], b[key])
            else:
                result[key] = a[key]
        for key in b:
            if key not in a:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = []
        for item in a + b:
            if item not in result:
                result.append(item)
        return result
    else:
        return b


