import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

function dijkstra(nodes: string[], edges: Edge[], source: string): Map<string, number> {
    const adj: Map<string, { node: string; weight: number }[]> = new Map();
    for (const node of nodes) {
        adj.set(node, []);
    }
    for (const edge of edges) {
        adj.get(edge.from)!.push({ node: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ node: edge.from, weight: edge.weight });
    }

    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of nodes) {
        dist.set(node, Infinity);
    }
    dist.set(source, 0);

    for (let i = 0; i < nodes.length; i++) {
        let u: string | null = null;
        let minDist = Infinity;
        for (const node of nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                u = node;
            }
        }

        if (u === null) break;

        visited.add(u);

        for (const { node: v, weight: w } of adj.get(u)!) {
            if (!visited.has(v)) {
                const newDist = dist.get(u)! + w;
                if (newDist < dist.get(v)!) {
                    dist.set(v, newDist);
                }
            }
        }
    }

    return dist;
}

