import Foundation

let filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a48q6jxk/graph.json"
let data = try! Data(contentsOf: URL(fileURLWithPath: filePath))
let json = try! JSONSerialization.jsonObject(with: data) as! [String: Any]

let nodes = json["nodes"] as! [String]
let edges = json["edges"] as! [[String: Any]]

var adj: [String: [(String, Double)]] = [:]
for node in nodes {
    adj[node] = []
}
for edge in edges {
    let from = edge["from"] as! String
    let to = edge["to"] as! String
    let weight = edge["weight"] as! Double
    adj[from]?.append((to, weight))
    adj[to]?.append((from, weight))
}

var dist: [String: Double] = [:]
var visited: Set<String> = []
for node in nodes {
    dist[node] = Double.greatestFiniteMagnitude
}
dist["A"] = 0

while visited.count < nodes.count {
    var minNode: String? = nil
    var minDist = Double.greatestFiniteMagnitude
    for node in nodes where !visited.contains(node) {
        if let d = dist[node], d < minDist {
            minDist = d
            minNode = node
        }
    }
    guard let current = minNode else { break }
    visited.insert(current)
    if let neighbors = adj[current] {
        for (neighbor, weight) in neighbors where !visited.contains(neighbor) {
            let newDist = dist[current]! + weight
            if newDist < dist[neighbor]! {
                dist[neighbor] = newDist
            }
        }
    }
}

print("=== Shortest Paths from A ===")
print("")
for node in nodes.sorted() {
    let d = dist[node]!
    if d == Double.greatestFiniteMagnitude {
        print("A -> \(node): unreachable")
    } else if d == d.rounded() {
        print("A -> \(node): \(Int(d))")
    } else {
        print("A -> \(node): \(d)")
    }
}

