import java.io.*;
import java.util.*;
import java.text.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a48q6jxk/employees.csv";

        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String header = br.readLine();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        String line;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(",");
            if (parts.length < 6) continue;
            String name = parts[1].trim();
            String department = parts[2].trim();
            String salaryStr = parts[3].trim().replace("$", "").replace(",", "");
            double salary = Double.parseDouble(salaryStr);

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCount.put(department, deptCount.getOrDefault(department, 0) + 1);

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }

            totalBudget += salary;
        }
        br.close();

        DecimalFormat avgFormat = new DecimalFormat("#,##0.00");
        DecimalFormat intFormat = new DecimalFormat("#,##0");

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append("  ").append(entry.getKey()).append(": $").append(avgFormat.format(avg)).append("\n");
        }

        sb.append("\n");
        sb.append("Highest Paid: ").append(highestName).append(" ($").append(intFormat.format(Math.round(highestSalary))).append(")\n");

        sb.append("\n");
        sb.append("Departments with >2 employees:\n");

        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                sb.append("  ").append(entry.getKey()).append(" (").append(entry.getValue()).append(" employees)\n");
            }
        }

        sb.append("\n");
        sb.append("Total Budget: $").append(intFormat.format(Math.round(totalBudget))).append("\n");

        System.out.print(sb.toString());
    }
}

