      lines.push(`Total: $${filtered.reduce((sum, p) => sum + p.price, 0).toFixed(2)}`);

      process.stdout.write(lines.join('\n') + '\n');
    });
  });

  req.on('error', (err: Error) => {
    process.stderr.write(err.message + '\n');
    process.exit(1);
  });

  req.end();
}

