        List<String[]> products = parseProducts(json);

        List<String[]> filtered = new ArrayList<>();
        for (String[] p : products) {
            double price = Double.parseDouble(p[2]);
            if (price > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort(Comparator.comparing(p -> p[1]));

