        System.out.printf("Total: $%.2f%n", total);
    }

    static List<String[]> parseProducts(String json) {
        List<String[]> result = new ArrayList<>();
        if (json.startsWith("[")) json = json.substring(1);
        if (json.endsWith("]")) json = json.substring(0, json.length() - 1);

        int i = 0;
        while (i < json.length()) {
            while (i < json.length() && json.charAt(i) != '{') i++;
            if (i >= json.length()) break;
            int start = i;
            int depth = 0;
            while (i < json.length()) {
                if (json.charAt(i) == '{') depth++;
                else if (json.charAt(i) == '}') {
                    depth--;
                    if (depth == 0) { i++; break; }
                }
                i++;
            }
            String obj = json.substring(start, i);
            String name = extractString(obj, "name");
            String price = extractNumber(obj, "price");
            if (name != null && price != null) {
                result.add(new String[]{"", name, price, "", ""});
            }
        }
        return result;
    }

    static String extractString(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return null;
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        if (idx >= obj.length()) return null;
        idx++;
        while (idx < obj.length() && obj.charAt(idx) == ' ') idx++;
        if (idx >= obj.length() || obj.charAt(idx) != '"') return null;
        idx++;
        int end = idx;
        while (end < obj.length() && obj.charAt(end) != '"') {
            if (obj.charAt(end) == '\\') end++;
            end++;
        }
        if (end >= obj.length()) return null;
        return obj.substring(idx, end);
    }

    static String extractNumber(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return null;
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        if (idx >= obj.length()) return null;
        idx++;
        while (idx < obj.length() && obj.charAt(idx) == ' ') idx++;
        int start = idx;
        while (idx < obj.length() && (Character.isDigit(obj.charAt(idx)) || obj.charAt(idx) == '.' || obj.charAt(idx) == '-' || obj.charAt(idx) == '+' || obj.charAt(idx) == 'e' || obj.charAt(idx) == 'E')) {
            idx++;
        }
        if (start == idx) return null;
        return obj.substring(start, idx);
    }
}

