import Foundation

func loadJSON(_ path: String) -> Any {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    return try! JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
}

func escape(_ s: String) -> String {
    var out = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\"": out += "\\\""
        case "\\": out += "\\\\"
        case "\n": out += "\\n"
        case "\r": out += "\\r"
        case "\t": out += "\\t"
        case "\u{08}": out += "\\b"
        case "\u{0C}": out += "\\f"
        default:
            if ch.value < 0x20 {
                out += String(format: "\\u%04x", ch.value)
            } else {
                out.unicodeScalars.append(ch)
            }
        }
    }
    out += "\""
    return out
}

func scalarString(_ value: Any) -> String {
    if value is NSNull { return "null" }
    if let s = value as? String { return escape(s) }
    if let n = value as? NSNumber {
        if CFBooleanGetTypeID() == CFGetTypeID(n) {
            return n.boolValue ? "true" : "false"
        }
        let d = n.doubleValue
        if d == d.rounded() && abs(d) < 1e15 {
            return String(Int64(d))
        }
        return String(d)
    }
    return "null"
}

func canonical(_ value: Any) -> String {
    if let dict = value as? [String: Any] {
        let keys = dict.keys.sorted()
        let parts = keys.map { k in "\(escape(k)): \(canonical(dict[k]!))" }
        return "{" + parts.joined(separator: ", ") + "}"
    }
    if let arr = value as? [Any] {
        return "[" + arr.map { canonical($0) }.joined(separator: ", ") + "]"
    }
    return scalarString(value)
}

func merge(_ a: Any, _ b: Any) -> Any {
    if let da = a as? [String: Any], let db = b as? [String: Any] {
        var result: [String: Any] = da
        for (k, v) in db {
            if let existing = result[k] {
                result[k] = merge(existing, v)
