        if keys.isEmpty { return "{}" }
        let parts = keys.map { k in
            inner + escape(k) + ": " + pretty(dict[k]!, indent: indent + 1)
        }
        return "{\n" + parts.joined(separator: "\n") + "\n" + pad + "}"
