    let mut sorted_hours: Vec<(&u8, &usize)> = hour_counts.iter().collect();
    sorted_hours.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((hour, count)) = sorted_hours.first() {
        println!("Busiest Hour: {:02}:00 ({} entries)", hour, count);
    }
}

