import Foundation

let A = [[1,2,3],[4,5,6],[7,8,9]]
let B = [[9,8,7],[6,5,4],[3,2,1]]

func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rows = A.count
    let cols = B[0].count
    var C = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            for k in 0..<A[0].count {
                C[i][j] += A[i][k] * B[k][j]
            }
        }
    }
    return C
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 { return M[0][0] }
    if n == 2 { return M[0][0]*M[1][1] - M[0][1]*M[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = Array(M.dropFirst())
        for i in 0..<minor.count {
            minor[i].remove(at: j)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * M[0][j] * determinant(minor)
    }
    return det
}

func formatMatrix(_ M: [[Int]]) -> [String] {
    return M.map { row in
        "  " + row.map { String(format: "%4d", $0) }.joined(separator: " ")
    }
}

