const rootDir = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a48q6jxk/project_tree';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(filePath: string): number {
  const stat = fs.statSync(filePath);
  if (stat.size === 0) return 0;
  const content: Buffer = fs.readFileSync(filePath);
  let newlines = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 10) newlines++;
  }
  if (content.length > 0 && content[content.length - 1] !== 10) {
    newlines++;
  }
  return newlines;
}

function walkDir(dir: string, root: string, visited: Set<string>): Map<string, FileStats[]> {
  const groups = new Map<string, FileStats[]>();

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return groups;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;

    const fullPath = path.join(dir, entry.name);
    const relPath = path.relative(root, fullPath).split(path.sep).join('/');

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      const subGroups = walkDir(fullPath, root, visited);
      for (const [ext, files] of subGroups) {
        if (!groups.has(ext)) groups.set(ext, []);
        groups.get(ext)!.push(...files);
      }
    } else if (entry.isFile()) {
      const stat = fs.statSync(fullPath);
      const chars = stat.size;
      const lines = countLines(fullPath);
      const ext = path.extname(entry.name);
      if (!groups.has(ext)) groups.set(ext, []);
      groups.get(ext)!.push({ relativePath: relPath, lines, chars });
    }
  }

  return groups;
}

