use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn get_extension(filename: &str) -> String {
    if let Some(dot_pos) = filename.rfind('.') {
        if dot_pos > 0 {
            return filename[dot_pos..].to_string();
        }
    }
    String::new()
}

fn count_lines(data: &[u8]) -> u64 {
    if data.is_empty() {
        return 0;
    }
    let mut count = data.iter().filter(|&&b| b == b'\n').count() as u64;
    if data[data.len() - 1] != b'\n' {
        count += 1;
    }
    count
}

fn walk(dir: &Path, root: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for item in entries {
        let item = match item {
            Ok(i) => i,
            Err(_) => continue,
        };

        let path = item.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(&path, root, files);
        } else if path.is_file() {
            let rel = path.strip_prefix(root).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            let mut contents = Vec::new();
            if let Ok(mut f) = fs::File::open(&path) {
                let _ = f.read_to_end(&mut contents);
            }

            let chars = contents.len() as u64;
            let lines = count_lines(&contents);

            files.push((rel_str, lines, chars));
        }
    }
}

