#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value json_value;

typedef struct {
    char *key;
    json_value *value;
} json_pair;

struct json_value {
    json_type type;
    int boolean;
    double number;
    char *string;
    json_value **items;
    int item_count;
    int item_cap;
    json_pair *pairs;
    int pair_count;
    int pair_cap;
};

static json_value *json_new(json_type t) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = t;
    return v;
}

static json_value *json_new_string(const char *s, int len) {
    json_value *v = json_new(JSON_STRING);
    v->string = (char *)malloc(len + 1);
    memcpy(v->string, s, len);
    v->string[len] = '\0';
    return v;
}

static json_value *json_new_number(double d) {
    json_value *v = json_new(JSON_NUMBER);
    v->number = d;
    return v;
}

static json_value *json_new_bool(int b) {
    json_value *v = json_new(JSON_BOOL);
    v->boolean = b;
    return v;
}

static json_value *json_new_null(void) {
    return json_new(JSON_NULL);
}

static json_value *json_new_array(void) {
    json_value *v = json_new(JSON_ARRAY);
    v->item_cap = 4;
    v->items = (json_value **)malloc(sizeof(json_value *) * v->item_cap);
    v->item_count = 0;
    return v;
}

static json_value *json_new_object(void) {
    json_value *v = json_new(JSON_OBJECT);
    v->pair_cap = 4;
    v->pairs = (json_pair *)malloc(sizeof(json_pair) * v->pair_cap);
    v->pair_count = 0;
    return v;
}

static void array_push(json_value *arr, json_value *item) {
    if (arr->item_count >= arr->item_cap) {
        arr->item_cap *= 2;
        arr->items = (json_value **)realloc(arr->items, sizeof(json_value *) * arr->item_cap);
    }
    arr->items[arr->item_count++] = item;
}

static void object_add(json_value *obj, char *key, json_value *val) {
    if (obj->pair_count >= obj->pair_cap) {
        obj->pair_cap *= 2;
        obj->pairs = (json_pair *)realloc(obj->pairs, sizeof(json_pair) * obj->pair_cap);
    }
    obj->pairs[obj->pair_count].key = key;
    obj->pairs[obj->pair_count].value = val;
    obj->pair_count++;
}

/* Parser */
static const char *src;
static int src_len;
static int pos;

static void skip_ws(void) {
    while (pos < src_len) {
        char c = src[pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
        else break;
    }
}

static json_value *parse_value(void);

static json_value *parse_string_raw(void) {
    /* assumes current char is '"' */
    pos++; /* skip opening quote */
    char *buf = (char *)malloc(4096);
    int blen = 0, bcap = 4096;
    buf[0] = '\0';
    while (pos < src_len && src[pos] != '"') {
        char c = src[pos];
        if (c == '\\') {
            pos++;
            if (pos >= src_len) break;
            char e = src[pos];
            char out = 0;
            switch (e) {
                case '"': out = '"'; break;
                case '\\': out = '\\'; break;
                case '/': out = '/'; break;
                case 'b': out = '\b'; break;
                case 'f': out = '\f'; break;
                case 'n': out = '\n'; break;
                case 'r': out = '\r'; break;
                case 't': out = '\t'; break;
                case 'u': {
                    /* parse 4 hex digits */
                    if (pos + 4 < src_len) {
                        unsigned int code = 0;
                        for (int i = 0; i < 4; i++) {
                            char h = src[pos + 1 + i];
                            code <<= 4;
                            if (h >= '0' && h <= '9') code |= (h - '0');
                            else if (h >= 'a' && h <= 'f') code |= (h - 'a' + 10);
                            else if (h >= 'A' && h <= 'F') code |= (h - 'A' + 10);
                        }
                        pos += 3; /* we'll advance past the 4th hex digit below */
                        /* encode as UTF-8 */
                        if (code < 0x80) {
                            out = (char)code;
                        } else if (code < 0x800) {
                            /* need 2 bytes - handle specially */
                            if (blen + 2 >= bcap) { bcap *= 2; buf = (char *)realloc(buf, bcap); }
                            buf[blen++] = (char)(0xC0 | (code >> 6));
                            buf[blen++] = (char)(0x80 | (code & 0x3F));
                            buf[blen] = '\0';
                            pos++;
                            continue;
                        } else {
                            if (blen + 3 >= bcap) { bcap *= 2; buf = (char *)realloc(buf, bcap); }
                            buf[blen++] = (char)(0xE0 | (code >> 12));
                            buf[blen++] = (char)(0x80 | ((code >> 6) & 0x3F));
                            buf[blen++] = (char)(0x80 | (code & 0x3F));
                            buf[blen] = '\0';
                            pos++;
                            continue;
                        }
                    }
                    break;
                }
                default: out = e; break;
            }
            pos++;
            if (blen + 1 >= bcap) { bcap *= 2; buf = (char *)realloc(buf, bcap); }
            buf[blen++] = out;
            buf[blen] = '\0';
        } else {
            if (blen + 1 >= bcap) { bcap *= 2; buf = (char *)realloc(buf, bcap); }
            buf[blen++] = c;
            buf[blen] = '\0';
            pos++;
        }
    }
    pos++; /* skip closing quote */
    if (blen + 1 >= bcap) { bcap = blen + 1; buf = (char *)realloc(buf, bcap); }
    return json_new_string(buf, blen);
}

static json_value *parse_number(void) {
    int start = pos;
    while (pos < src_len) {
        char c = src[pos];
        if ((c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E')
            pos++;
        else break;
    }
    char *numstr = (char *)malloc(pos - start + 1);
    memcpy(numstr, src + start, pos - start);
    numstr[pos - start] = '\0';
    double d = strtod(numstr, NULL);
    free(numstr);
    return json_new_number(d);
}

static json_value *parse_array(void) {
    pos++; /* skip [ */
    json_value *arr = json_new_array();
    skip_ws();
    if (pos < src_len && src[pos] == ']') {
        pos++;
        return arr;
    }
    while (1) {
        skip_ws();
        json_value *item = parse_value();
        array_push(arr, item);
        skip_ws();
        if (pos < src_len && src[pos] == ',') {
            pos++;
        } else if (pos < src_len && src[pos] == ']') {
            pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static json_value *parse_object(void) {
    pos++; /* skip { */
    json_value *obj = json_new_object();
    skip_ws();
    if (pos < src_len && src[pos] == '}') {
        pos++;
        return obj;
    }
    while (1) {
        skip_ws();
        /* parse key */
        if (pos >= src_len || src[pos] != '"') break;
        json_value *kv = parse_string_raw();
        char *key = kv->string;
        free(kv);
        skip_ws();
        if (pos >= src_len || src[pos] != ':') break;
        pos++; /* skip : */
        skip_ws();
        json_value *val = parse_value();
        object_add(obj, key, val);
        skip_ws();
        if (pos < src_len && src[pos] == ',') {
            pos++;
        } else if (pos < src_len && src[pos] == '}') {
            pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static json_value *parse_value(void) {
    skip_ws();
    if (pos >= src_len) return json_new_null();
    char c = src[pos];
    if (c == '{') return parse_object();
    if (c == '[') return parse_array();
    if (c == '"') return parse_string_raw();
    if (c == 't' && pos + 3 < src_len && memcmp(src + pos, "true", 4) == 0) {
        pos += 4;
        return json_new_bool(1);
    }
    if (c == 'f' && pos + 4 < src_len && memcmp(src + pos, "false", 5) == 0) {
        pos += 5;
        return json_new_bool(0);
    }
    if (c == 'n' && pos + 3 < src_len && memcmp(src + pos, "null", 4) == 0) {
        pos += 4;
        return json_new_null();
    }
    if (c == '-' || (c >= '0' && c <= '9')) return parse_number();
    /* fallback */
    pos++;
    return json_new_null();
