        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next();
            let value = self.parse_value();
            items.push((key, value));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(items)
    }
}

fn dechunk(data: &str) -> String {
    let mut result = String::new();
    let mut i = 0;
    let len = data.len();
    while i < len {
        let line_end = match data[i..].find("\r\n") {
            Some(p) => i + p,
            None => break,
        };
        let size_str = data[i..line_end].trim();
        let size = match usize::from_str_radix(size_str, 16) {
            Ok(s) => s,
            Err(_) => break,
        };
        if size == 0 {
            break;
        }
        let chunk_start = line_end + 2;
        let chunk_end = chunk_start + size;
        if chunk_end <= len {
