import Foundation

let baseDir = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a48q6jxk/project_tree"
let fileManager = FileManager.default

struct FileEntry {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var filesByExtension: [String: [FileEntry]] = [:]
var visitedDirs: Set<String> = []

func processFile(_ url: URL) {
    guard let data = try? Data(contentsOf: url) else { return }
    let chars = data.count

    var lines = 0
    if !data.isEmpty {
        let newlineCount = data.reduce(0) { $0 + ($1 == 10 ? 1 : 0) }
        if data[data.count - 1] != 10 {
            lines = newlineCount + 1
        } else {
            lines = newlineCount
        }
    }

    let fullPath = url.path
    var relativePath = fullPath
    let prefix = baseDir + "/"
    if relativePath.hasPrefix(prefix) {
        relativePath = String(relativePath.dropFirst(prefix.count))
    }

    let ext = url.pathExtension
    let extKey = ext.isEmpty ? "" : "." + ext

    let entry = FileEntry(relativePath: relativePath, lines: lines, chars: chars)
    filesByExtension[extKey, default: []].append(entry)
}

func walkDirectory(_ url: URL) {
    let path = url.path
    if visitedDirs.contains(path) { return }

    var isDir: ObjCBool = false
    guard fileManager.fileExists(atPath: path, isDirectory: &isDir) else { return }
    guard isDir.boolValue else { return }

    visitedDirs.insert(path)

    guard let contents = try? fileManager.contentsOfDirectory(
        at: url,
        includingPropertiesForKeys: [.isSymbolicLinkKey],
        options: []
    ) else { return }

    for child in contents {
        let isSymlink = (try? child.resourceValues(forKeys: [.isSymbolicLinkKey]))?.isSymbolicLink ?? false
        if isSymlink {
            continue
        }

        var childIsDir: ObjCBool = false
        fileManager.fileExists(atPath: child.path, isDirectory: &childIsDir)

        if childIsDir.boolValue {
            walkDirectory(child)
        } else {
            processFile(child)
        }
    }
}

