#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 8192

typedef struct {
    char **items;
    int count;
    int capacity;
} StrArray;

static void strarray_init(StrArray *sa) {
    sa->items = NULL;
    sa->count = 0;
    sa->capacity = 0;
}

static void strarray_push(StrArray *sa, const char *s) {
    if (sa->count >= sa->capacity) {
        sa->capacity = sa->capacity ? sa->capacity * 2 : 128;
        sa->items = (char **)realloc(sa->items, (size_t)sa->capacity * sizeof(char *));
        if (!sa->items) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    sa->items[sa->count] = strdup(s);
    sa->count++;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

