    skip_ws(p);
    if (**p != '"') return NULL;
    (*p)++;
    const char *start = *p;
    while (**p && **p != '"') {
        if (**p == '\\')
            (*p)++;
        (*p)++;
    }
    size_t len = (size_t)(*p - start);
    char *s = (char *)malloc(len + 1);
    if (!s) return NULL;
    memcpy(s, start, len);
    s[len] = '\0';
    if (**p == '"') (*p)++;
    return s;
}

