use std::fs;
use std::collections::HashMap;

enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Parser {
    s: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { s: s.chars().collect(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len() && self.s[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.s.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_ws();
        let got = self.next();
        assert_eq!(got, Some(c), "Expected '{}' at pos {}", c, self.pos);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some('{') => Json::Obj(self.parse_obj()),
            Some('[') => Json::Arr(self.parse_arr()),
            Some('"') => Json::Str(self.parse_str()),
            Some('t') => {
                self.parse_lit("true");
                Json::Bool(true)
            }
            Some('f') => {
                self.parse_lit("false");
                Json::Bool(false)
            }
            Some('n') => {
                self.parse_lit("null");
                Json::Null
            }
            _ => Json::Num(self.parse_num()),
        }
    }

    fn parse_lit(&mut self, lit: &str) {
        for c in lit.chars() {
            assert_eq!(self.next(), Some(c), "Expected literal '{}' at pos {}", lit, self.pos);
        }
    }

    fn parse_str(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.next().unwrap();
                            code = code * 16 + hex_val(c);
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => {}
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_num(&mut self) -> f64 {
        self.skip_ws();
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        s.parse().unwrap()
    }

    fn parse_arr(&mut self) -> Vec<Json> {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') {
            self.next();
            return arr;
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array at pos {}", self.pos),
            }
        }
        arr
    }

    fn parse_obj(&mut self) -> Vec<(String, Json)> {
        self.expect('{');
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.next();
            return obj;
        }
        loop {
            self.skip_ws();
            let key = self.parse_str();
            self.expect(':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}' in object at pos {}", self.pos),
            }
        }
        obj
    }
}

fn hex_val(c: char) -> u32 {
    match c {
        '0'..='9' => c as u32 - '0' as u32,
        'a'..='f' => c as u32 - 'a' as u32 + 10,
        'A'..='F' => c as u32 - 'A' as u32 + 10,
        _ => 0,
    }
}

