    FileInfo *files;
    int cap;
} ExtGroup;

static FileInfo *all_files = NULL;
static int num_files = 0;
static int cap_files = 0;

static char *strdup_s(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

static void add_file(const char *relpath, long lines, long chars) {
    if (num_files >= cap_files) {
        cap_files = cap_files ? cap_files * 2 : 128;
        all_files = realloc(all_files, (size_t)cap_files * sizeof(FileInfo));
    }
    all_files[num_files].relpath = strdup_s(relpath);
    all_files[num_files].lines = lines;
    all_files[num_files].chars = chars;
    num_files++;
}

static long count_lines(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return 0;
    long count = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') count++;
    }
    fclose(f);
    return count;
}

static void walk(const char *dir, const char *reldir) {
    DIR *d = opendir(dir);
    if (!d) return;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        size_t dl = strlen(dir);
        size_t nl = strlen(entry->d_name);
        char *fullpath = malloc(dl + 1 + nl + 1);
        snprintf(fullpath, dl + 1 + nl + 1, "%s/%s", dir, entry->d_name);

        char *relpath;
        if (reldir[0] == '\0') {
            relpath = strdup_s(entry->d_name);
        } else {
            size_t rl = strlen(reldir);
            relpath = malloc(rl + 1 + nl + 1);
            snprintf(relpath, rl + 1 + nl + 1, "%s/%s", reldir, entry->d_name);
        }

        struct stat st;
        if (lstat(fullpath, &st) == 0) {
            if (S_ISREG(st.st_mode)) {
                long lines = count_lines(fullpath);
                long chars = (long)st.st_size;
                add_file(relpath, lines, chars);
            } else if (S_ISDIR(st.st_mode)) {
                walk(fullpath, relpath);
            }
        }

        free(relpath);
        free(fullpath);
    }
    closedir(d);
}

static int cmp_ext(const void *a, const void *b) {
    const ExtGroup *ga = *(ExtGroup *const *)a;
    const ExtGroup *gb = *(ExtGroup *const *)b;
    return strcmp(ga->ext, gb->ext);
}

static int cmp_file(const void *a, const void *b) {
    const FileInfo *fa = *(FileInfo *const *)a;
    const FileInfo *fb = *(FileInfo *const *)b;
    return strcmp(fa->relpath, fb->relpath);
}

int main(void) {
    walk(BASE_DIR, "");

    ExtGroup *groups = NULL;
    int num_groups = 0;
    int cap_groups = 0;

    for (int i = 0; i < num_files; i++) {
        const char *rp = all_files[i].relpath;
        const char *slash = strrchr(rp, '/');
        const char *basename = slash ? slash + 1 : rp;
        const char *dot = strrchr(basename, '.');

        char *ext;
        if (dot && dot != basename) {
            ext = strdup_s(dot);
        } else {
            ext = strdup_s("");
        }

        int found = -1;
        for (int g = 0; g < num_groups; g++) {
            if (strcmp(groups[g].ext, ext) == 0) {
                found = g;
                break;
            }
        }

        if (found == -1) {
            if (num_groups >= cap_groups) {
                cap_groups = cap_groups ? cap_groups * 2 : 16;
                groups = realloc(groups, (size_t)cap_groups * sizeof(ExtGroup));
            }
            groups[num_groups].ext = ext;
            groups[num_groups].count = 0;
            groups[num_groups].total_lines = 0;
            groups[num_groups].total_chars = 0;
            groups[num_groups].files = NULL;
            groups[num_groups].cap = 0;
            num_groups++;
        } else {
