        }

        ExtGroup *grp = &groups[found];
        if (grp->count >= grp->cap) {
            grp->cap = grp->cap ? grp->cap * 2 : 16;
            grp->files = realloc(grp->files, (size_t)grp->cap * sizeof(FileInfo));
        }
        grp->files[grp->count] = all_files[i];
