        for (int g = 0; g < num_groups; g++) gptrs[g] = &groups[g];
        qsort(gptrs, (size_t)num_groups, sizeof(ExtGroup *), cmp_ext);
        ExtGroup *sorted = malloc((size_t)num_groups * sizeof(ExtGroup));
