    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0, total_lines = 0, total_chars = 0;

    for (int g = 0; g < num_groups; g++) {
        printf("Extension: %s\n", groups[g].ext);
        printf("  Files: %d\n", groups[g].count);
        printf("  Total Lines: %ld\n", groups[g].total_lines);
        printf("  Total Characters: %ld\n", groups[g].total_chars);
        for (int f = 0; f < groups[g].count; f++) {
            printf("    %s: %ld lines, %ld chars\n",
                   groups[g].files[f].relpath,
