struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { data: s.as_bytes(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len()
            && matches!(self.data[self.pos], b' ' | b'\t' | b'\n' | b'\r')
        {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<u8> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: u8) -> Result<(), String> {
        self.skip_whitespace();
        match self.next() {
            Some(x) if x == c => Ok(()),
            _ => Err(format!("Expected '{}'", c as char)),
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_whitespace();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Json::Str),
            Some(b't') => self.parse_literal("true", Json::Bool(true)),
            Some(b'f') => self.parse_literal("false", Json::Bool(false)),
            Some(b'n') => self.parse_literal("null", Json::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("Unexpected character at position {}", self.pos)),
        }
    }

    fn parse_literal(&mut self, lit: &str, val: Json) -> Result<Json, String> {
        for c in lit.bytes() {
            match self.next() {
                Some(x) if x == c => {}
                _ => return Err(format!("Expected literal '{}'", lit)),
            }
        }
        Ok(val)
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let mut bytes = Vec::new();
        loop {
            match self.next() {
                None => return Err("Unexpected end of string".into()),
                Some(b'"') => break,
                Some(b'\\') => match self.next() {
                    Some(b'"') => bytes.push(b'"'),
                    Some(b'\\') => bytes.push(b'\\'),
                    Some(b'/') => bytes.push(b'/'),
                    Some(b'b') => bytes.push(0x08),
                    Some(b'f') => bytes.push(0x0C),
                    Some(b'n') => bytes.push(b'\n'),
                    Some(b'r') => bytes.push(b'\r'),
                    Some(b't') => bytes.push(b'\t'),
                    Some(b'u') => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            let c = self.next().ok_or("Invalid unicode escape")?;
                            let d = (c as char)
                                .to_digit(16)
                                .ok_or("Invalid hex digit")?;
                            code = code * 16 + d;
                        }
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.next() == Some(b'\\') && self.next() == Some(b'u') {
                                let mut low = 0u32;
                                for _ in 0..4 {
                                    let c =
                                        self.next().ok_or("Invalid unicode escape")?;
                                    let d = (c as char)
                                        .to_digit(16)
                                        .ok_or("Invalid hex digit")?;
                                    low = low * 16 + d;
                                }
                                let cp =
                                    0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                let ch = char::from_u32(cp).ok_or("Invalid surrogate pair")?;
                                let mut buf = [0u8; 4];
                                bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            } else {
                                return Err("Invalid surrogate pair".into());
                            }
                        } else {
                            let ch = char::from_u32(code).ok_or("Invalid unicode code point")?;
                            let mut buf = [0u8; 4];
                            bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => return Err("Invalid escape sequence".into()),
                },
                Some(c) => {
                    if c < 0x80 {
                        bytes.push(c);
                    } else {
                        let mut char_bytes = vec![c];
                        let extra = if c >= 0xF0 {
                            3
                        } else if c >= 0xE0 {
                            2
                        } else if c >= 0xC0 {
                            1
                        } else {
                            0
                        };
                        for _ in 0..extra {
                            let b = self.next().ok_or("Invalid UTF-8")?;
                            char_bytes.push(b);
                        }
                        bytes.extend_from_slice(&char_bytes);
                    }
                }
            }
        }
        String::from_utf8(bytes).map_err(|e| e.to_string())
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') {
            self.pos += 1;
        }
        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
            }
        } else {
            return Err("Invalid number".into());
        }
        let mut is_float = false;
        if self.peek() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) {
                return Err("Expected digit after '.'".into());
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
            }
        }
        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            is_float = true;
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') {
                self.pos += 1;
            }
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) {
                return Err("Expected digit in exponent".into());
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
            }
        }
        let num_str =
            std::str::from_utf8(&self.data[start..self.pos]).map_err(|e| e.to_string())?;
        if is_float {
            num_str
                .parse::<f64>()
                .map(Json::Float)
                .map_err(|e| e.to_string())
        } else {
            num_str
                .parse::<i64>()
                .map(Json::Int)
                .map_err(|e| e.to_string())
        }
    }

    fn parse_array(&mut self) -> Result<Json, String> {
        self.expect(b'[')?;
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Ok(Json::Array(items));
        }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(b',') => continue,
                Some(b']') => break,
                _ => return Err("Expected ',' or ']' in array".into()),
            }
        }
        Ok(Json::Array(items))
    }

    fn parse_object(&mut self) -> Result<Json, String> {
        self.expect(b'{')?;
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Ok(Json::Object(map));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.expect(b':')?;
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_whitespace();
            match self.next() {
                Some(b',') => continue,
                Some(b'}') => break,
                _ => return Err("Expected ',' or '}' in object".into()),
            }
        }
        Ok(Json::Object(map))
    }
}

fn parse_json(s: &str) -> Result<Json, String> {
    let mut parser = Parser::new(s);
    let val = parser.parse_value()?;
    parser.skip_whitespace();
    if parser.pos != parser.data.len() {
        return Err("Trailing content after JSON value".into());
    }
    Ok(val)
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let inner_pad = "  ".repeat(indent + 1);
    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Int(n) => n.to_string(),
        Json::Float(f) => {
            let s = format!("{}", f);
            if !s.contains('.') && !s.contains('e') && !s.contains('E') {
                format!("{}.0", s)
            } else {
                s
            }
        }
        Json::Str(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let mut parts = Vec::new();
            for item in arr {
                parts.push(format!("{}{}", inner_pad, serialize(item, indent + 1)));
            }
            format!("[\n{}\n{}]", parts.join(",\n"), pad)
        }
        Json::Object(obj) => {
            if obj.is_empty() {
                return "{}".to_string();
            }
            let mut parts = Vec::new();
            for (k, v) in obj {
                parts.push(format!(
                    "{}\"{}\": {}",
                    inner_pad,
                    escape_string(k),
                    serialize(v, indent + 1)
                ));
            }
            format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
        }
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (a, b) {
        (Json::Object(mut oa), Json::Object(ob)) => {
            for (k, v) in ob {
                match oa.remove(&k) {
                    Some(existing) => {
                        oa.insert(k, deep_merge(existing, v));
                    }
                    None => {
                        oa.insert(k, v);
                    }
                }
            }
            Json::Object(oa)
        }
        (Json::Array(mut aa), Json::Array(ab)) => {
            for item in ab {
                if !aa.contains(&item) {
                    aa.push(item);
                }
            }
            Json::Array(aa)
        }
        (_, b) => b,
    }
}

